content.css:
.profile-lens {
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  width: 100%;
  height: 100%;
  overflow: hidden;
  font-family: "Segoe UI", wf_segoe-ui_normal, helvetica, arial, sans-serif;
  font-size: 12px;
  color: var(--profile-lens-foreground, #252423);
  background: transparent;
}
.profile-lens *,
.profile-lens *::before,
.profile-lens *::after {
  box-sizing: border-box;
}
.profile-lens:focus-visible {
  outline: 2px solid var(--profile-lens-foreground, #252423);
  outline-offset: -2px;
}
.profile-lens [hidden] {
  display: none !important;
}
.profile-lens-body {
  display: flex;
  flex: 1 1 auto;
  min-height: 0;
  min-width: 0;
  order: 3;
}
.profile-lens-chart {
  position: relative;
  flex: 1 1 auto;
  min-width: 0;
  min-height: 0;
  overflow: hidden;
}
.profile-lens-chart > svg {
  display: block;
  width: 100%;
  height: 100%;
  max-width: 100%;
  max-height: 100%;
}
.profile-lens-context {
  position: absolute;
  inset: 0;
  overflow: hidden;
  z-index: 0;
  max-width: 100%;
  max-height: 100%;
}
.profile-lens-context:focus-visible {
  outline: 2px solid var(--profile-lens-foreground, #252423);
  outline-offset: -2px;
}
.profile-lens-context.profile-lens-context-navigation-active {
  cursor: grab;
  touch-action: none;
  user-select: none;
}
.profile-lens-context.profile-lens-context-panning {
  cursor: grabbing;
}
.profile-lens-context-canvas,
.profile-lens-context-svg {
  position: absolute;
  inset: 0;
  display: block;
  max-width: 100%;
  max-height: 100%;
}
.profile-lens-context-canvas {
  z-index: 0;
  transform-origin: 0 0;
}
.profile-lens-context-svg {
  z-index: 1;
  pointer-events: none;
}
.profile-lens-context-attribution {
  position: absolute;
  inset-inline-end: 4px;
  bottom: 2px;
  z-index: 2;
  max-width: calc(100% - 8px);
  overflow: hidden;
  color: var(--profile-lens-muted, #605E5C);
  font-size: 8px;
  line-height: 10px;
  text-overflow: ellipsis;
  white-space: nowrap;
  pointer-events: none;
}
.profile-lens-context-help {
  position: absolute;
  inset-inline-start: 4px;
  bottom: 2px;
  z-index: 2;
  max-width: calc(100% - 96px);
  overflow: hidden;
  color: var(--profile-lens-muted, #605E5C);
  font-size: 9px;
  line-height: 11px;
  text-overflow: ellipsis;
  white-space: nowrap;
  pointer-events: none;
}
.profile-lens-context-reset {
  position: absolute;
  inset-inline-end: 4px;
  top: 4px;
  z-index: 3;
  min-width: 28px;
  min-height: 24px;
  max-width: calc(100% - 8px);
  padding: 2px 6px;
  overflow: hidden;
  border: 1px solid var(--profile-lens-border, #E1DFDD);
  border-radius: 2px;
  color: var(--profile-lens-foreground, #252423);
  background: var(--profile-lens-background, #FFF);
  font: inherit;
  text-overflow: ellipsis;
  white-space: nowrap;
  cursor: pointer;
}
.profile-lens-context-reset:focus,
.profile-lens-context-reset:focus-visible {
  outline: 2px solid var(--profile-lens-selected, #252423);
  outline-offset: 1px;
}
.profile-lens-context-reset:disabled {
  cursor: default;
  opacity: 0.6;
  pointer-events: none;
}
.profile-lens-context-camera-layer,
.profile-lens-context-outline-layer {
  transform-origin: 0 0;
}
.profile-lens-context-fixed-layer,
.profile-lens-context-probe,
.profile-lens-context-outline-layer {
  pointer-events: none;
}
.profile-lens-context-outline,
.profile-lens-context-outline * {
  vector-effect: non-scaling-stroke;
}
.profile-lens-profile-svg {
  position: relative;
  z-index: 2;
  pointer-events: none;
}
.profile-lens-profile-svg .profile-lens-target {
  pointer-events: auto;
}
.profile-lens-header {
  display: flex;
  align-items: baseline;
  gap: 4px;
  flex: 0 0 auto;
  min-width: 0;
  padding: 2px 4px;
  overflow: hidden;
  order: 1;
}
.profile-lens-header .profile-lens-header-title {
  flex: 0 1 auto;
  min-width: 0;
  margin: 0;
  overflow: hidden;
  font-weight: 600;
  line-height: 1.2;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.profile-lens-header .profile-lens-header-subtitle {
  flex: 1 1 auto;
  min-width: 0;
  margin: 0;
  overflow: hidden;
  color: #605E5C;
  font-size: 11px;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.profile-lens-entities {
  flex: 0 0 148px;
  width: 148px;
  max-width: 148px;
  overflow-y: auto;
  border-right: 1px solid #E1DFDD;
}
.profile-lens-entity-option {
  padding: 2px 6px;
  cursor: default;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.profile-lens-entity-option[aria-selected="true"] {
  font-weight: 600;
  text-decoration: underline;
}
.profile-lens-entity-option:focus-visible {
  outline: 2px solid #252423;
  outline-offset: -2px;
}
.profile-lens-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  padding: 2px 4px;
  order: 4;
}
.profile-lens-legend-item {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}
.profile-lens-legend-swatch {
  display: inline-block;
  width: 10px;
  height: 10px;
  border: 1px solid #252423;
}
.profile-lens-period {
  padding: 2px 4px;
  order: 5;
}
.profile-lens-period-slider {
  display: inline-block;
  padding: 1px 6px;
  border: 1px solid #E1DFDD;
  border-radius: 2px;
}
.profile-lens-period-slider:focus-visible {
  outline: 2px solid #252423;
  outline-offset: 1px;
}
.profile-lens-status {
  padding: 0 4px;
  color: #605E5C;
  font-size: 11px;
  order: 6;
}
.profile-lens-status p {
  margin: 0;
}
.profile-lens-diagnostics {
  margin: 2px 0 0;
  padding-left: 14px;
}
.profile-lens-diagnostic.profile-lens-error {
  color: #A80000;
}
.profile-lens-diagnostic.profile-lens-warning {
  color: #8A6100;
}
.profile-lens-landing {
  flex: 1 1 auto;
  min-height: 0;
  padding: 8px;
  overflow-y: auto;
  order: 0;
}
.profile-lens-landing h2 {
  margin: 0 0 4px;
  font-size: 14px;
}
.profile-lens-landing p {
  margin: 0 0 4px;
}
.profile-lens-landing .profile-lens-landing-steps li[data-complete="true"] {
  color: #605E5C;
  text-decoration: line-through;
}
.profile-lens-landing .profile-lens-landing-note {
  color: #605E5C;
  font-size: 11px;
}
.profile-lens-table {
  flex: 0 1 auto;
  min-height: 0;
  overflow: auto;
  order: 7;
}
.profile-lens-table table {
  border-collapse: collapse;
  font-size: 11px;
}
.profile-lens-table th,
.profile-lens-table td {
  border: 1px solid #E1DFDD;
  padding: 1px 4px;
  text-align: start;
}
.profile-lens-table-sr,
.profile-lens-context-semantic,
.profile-lens-probe-announcement,
.profile-lens-status-sr {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}
.profile-lens-target {
  cursor: default;
}
.profile-lens-target:focus-visible rect,
.profile-lens-target:focus rect {
  outline: 2px solid #252423;
  stroke: #252423;
  stroke-width: 2;
}
.profile-lens-error {
  color: #A80000;
}
.profile-lens-empty {
  pointer-events: none;
}
.profile-lens-empty-message,
.profile-lens-empty-guidance {
  user-select: none;
}
.profile-lens-reduced-motion * {
  transition: none !important;
  animation: none !important;
}
.profile-lens-high-contrast .profile-lens-legend-swatch {
  border-width: 2px;
}
.profile-lens-high-contrast .profile-lens-context {
  color: var(--profile-lens-foreground);
  background: var(--profile-lens-background);
}
.profile-lens-high-contrast .profile-lens-context-help,
.profile-lens-high-contrast .profile-lens-context-attribution {
  color: var(--profile-lens-foreground);
  background: var(--profile-lens-background);
}
.profile-lens-high-contrast .profile-lens-context-reset {
  border-width: 2px;
  border-color: var(--profile-lens-foreground);
  color: var(--profile-lens-foreground);
  background: var(--profile-lens-background);
}
.profile-lens-high-contrast .profile-lens-context-reset:disabled {
  opacity: 1;
  border-style: dashed;
}
@media (max-width: 120px), (max-height: 120px) {
  .profile-lens-context-help {
    display: none;
  }
  .profile-lens-context-reset {
    min-width: 24px;
    min-height: 20px;
    padding: 1px 3px;
    font-size: 9px;
  }
}
